'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var Float64Array = require( '@stdlib/array/float64' );
var pkg = require( './../package.json' ).name;
var dlarfb = require( './../lib/ndarray.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var SIDES = [
	'left',
	'right'
];
var TRANS = [
	'no-transpose',
	'transpose'
];
var DIRECTS = [
	'forward',
	'backward'
];
var STOREVS = [
	'columns',
	'rows'
];


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {string} side - operation side
* @param {string} trans - transpose operation
* @param {string} direct - direction
* @param {string} storev - storage format
* @param {PositiveInteger} N - number of columns
* @returns {Function} benchmark function
*/
function createBenchmark( order, side, trans, direct, storev, N ) {
	var work;
	var sv1;
	var sv2;
	var st1;
	var st2;
	var sc1;
	var sc2;
	var sw1;
	var sw2;
	var V;
	var T;
	var C;

	V = uniform( N*N, 0.0001, 0.001, {
		'dtype': 'float64'
	});
	T = uniform( N*N, 0.0001, 0.001, {
		'dtype': 'float64'
	});
	C = uniform( N*N, 0.0001, 0.001, {
		'dtype': 'float64'
	});
	work = new Float64Array( N*N );

	if ( isColumnMajor( order ) ) {
		sv1 = 1;
		sv2 = N;
		st1 = 1;
		st2 = N;
		sc1 = 1;
		sc2 = N;
		sw1 = 1;
		sw2 = N;
	} else {
		sv1 = N;
		sv2 = 1;
		st1 = N;
		st2 = 1;
		sc1 = N;
		sc2 = 1;
		sw1 = N;
		sw2 = 1;
	}

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dlarfb( side, trans, direct, storev, N, N, N, V, sv1, sv2, 0, T, st1, st2, 0, C, sc1, sc2, 0, work, sw1, sw2, 0 ); // eslint-disable-line max-len
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var direct;
	var storev;
	var trans;
	var side;
	var min;
	var max;
	var ord;
	var f;
	var i;
	var j;
	var k;
	var l;
	var m;
	var n;
	var N;

	min = 1; // 10^min
	max = 3; // 10^max

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( l = 0; l < SIDES.length; l++ ) {
			side = SIDES[ l ];
			for ( m = 0; m < TRANS.length; m++ ) {
				trans = TRANS[ m ];
				for ( n = 0; n < DIRECTS.length; n++ ) {
					direct = DIRECTS[ n ];
					for ( i = min; i <= max; i++ ) {
						N = floor( pow( pow( 10, i ), 1.0/2.0 ) );

						for ( j = 0; j < STOREVS.length; j++ ) { // eslint-disable-line max-depth
							storev = STOREVS[ j ];
							f = createBenchmark( ord, side, trans, direct, storev, N ); // eslint-disable-line max-len
							bench( pkg+'::matrix:ndarray:order='+ord+',side='+side+',trans='+trans+',direct='+direct+',storev='+storev+',N='+N+',size='+(N*N), f );
						}
					}
				}
			}
		}
	}
}

main();
